    name: { de: "105-Meilen-Handelszone", hu: "105 Mérföldes Kereskedelmi Övezet", ro: "Zona Comercială 105 Mile", en: "105 Mile Trade Zone"},
    image: "/poi-images/105-mile-trade-zone-economic-v2.webp",
    description: {
      de: "Die größte und wichtigste Grenzübergangsstelle an der Grenze zu China nahe Muse, durch die ein Großteil des bilateralen Handels fließt.",
      hu: "A legnagyobb és legfontosabb határátkelőhely a kínai határon Muse közelében, amelyen a kétoldalú kereskedelem nagy része áthalad.",
      ro: "Cel mai mare și mai important punct de trecere a frontierei de la granița cu China, lângă Muse, prin care trece mare parte din comerțul bilateral.",
      en: "The largest and most important border crossing station on the border with China near Muse, handling the bulk of bilateral trade.",
      es: "El puesto fronterizo más grande e importante en la frontera con China, cerca de Muse, a través del cual fluye gran parte del comercio bilateral.",
      pt: "O maior e mais importante posto fronteiriço na fronteira com a China, perto de Muse, por onde passa grande parte do comércio bilateral.",
      fr: "Le poste-frontière le plus grand et le plus important à la frontière avec la Chine, près de Muse, par lequel transite une grande partie du commerce bilatéral.",
    },
    facts: {
      de: [
        "Benannt nach der Entfernung zur Stadt Lashio (105 Meilen).",
        "Hier werden täglich Hunderte von Lastwagen abgefertigt."
      ],
      hu: [
        "Lashio városától mért távolságáról (105 mérföld) nevezték el.",
        "Naponta teherautók százait vámolják el itt."
      ],
      ro: [
        "Numit după distanța până la orașul Lashio (105 mile).",
        "Sute de camioane sunt procesate aici zilnic."
      ],
      en: [
        "Named for its distance from the city of Lashio (105 miles).",
        "Hundreds of trucks are processed here on a daily basis."
      ],
      es: ["Nombrada por la distancia a la ciudad de Lashio (105 millas).", "Aquí se despachan cientos de camiones diariamente."],
      pt: ["Nomeada pela distância até à cidade de Lashio (105 milhas).", "Aqui são processados centenas de camiões diariamente."],
      fr: ["Nommée d'après la distance jusqu'à la ville de Lashio (105 miles).", "Des centaines de camions y sont traités quotidiennement."],
    },
    descriptionAdvanced: {
      de: "Die 105-Meilen-Handelszone in Muse im Bundesstaat Shan ist das größte und wichtigste Tor für den Landhandel zwischen Myanmar und China. Sie liegt strategisch günstig an der Hauptstraße nach Mandalay und direkt gegenüber der chinesischen Stadt Ruili in der Provinz Yunnan. Diese Sonderhandelszone wickelt wertmäßig den größten Teil des gesamten Grenzhandels Myanmars ab, wobei Exporte wie Agrarprodukte, Obst, Reis und Meeresfrüchte sowie Importe wie Maschinen, Treibstoff und Konsumgüter im Vordergrund stehen. Die Zone verfügt über umfangreiche Logistikeinrichtungen, Zollstationen und Lagerhäuser, die für die Abwicklung tausender Lastwagen täglich ausgelegt sind. Wirtschaftlich ist dieser Standort das Rückgrat der myanmarisch-chinesischen Wirtschaftsbeziehungen und ein zentraler Bestandteil des China-Myanmar-Wirtschaftskorridors. Politische Instabilität und Grenzschließungen aufgrund von Konflikten oder Pandemien haben jedoch in der Vergangenheit zu erheblichen wirtschaftlichen Einbußen geführt.",
      hu: "A Shan állambeli Muse városában található 105 mérföldes kereskedelmi övezet Mianmar és Kína közötti szárazföldi kereskedelem legnagyobb és legfontosabb kapuja. Stratégiai helyen, a Mandalay-ba vezető főút mentén, közvetlenül a jünnani Ruili várossal szemben fekszik. Ez a különleges kereskedelmi övezet bonyolítja le Mianmar teljes határmenti forgalmának legnagyobb részét értékben kifejezve; a fő exportcikkek a mezőgazdasági termékek, gyümölcsök, rizs és tenger gyümölcsei, míg az importot gépek, üzemanyag és fogyasztási cikkek alkotják. Az övezet kiterjedt logisztikai létesítményekkel, vámállomásokkal és raktárakkal rendelkezik, amelyeket naponta több ezer teherautó kiszolgálására terveztek. Gazdaságilag ez a helyszín a mianmari-kínai kapcsolatok gerince és a Kína-Mianmar Gazdasági Folyosó központi eleme. A politikai instabilitás és a konfliktusok vagy járványok miatti határzárak azonban a múltban jelentős gazdasági veszteségeket okoztak.",
      ro: "Zona comercială de 105 mile din Muse, statul Shan, este cea mai mare și mai importantă poartă pentru comerțul terestru între Myanmar și China. Este situată strategic pe drumul principal către Mandalay, direct vizavi de orașul chinez Ruili din provincia Yunnan. Această zonă comercială specială gestionează cea mai mare parte a comerțului transfrontalier al Myanmarului în termeni de valoare, principalele exporturi fiind produsele agricole, fructele, orezul și fructele de mare, în timp ce importurile constau în utilaje, combustibil și bunuri de consum. Zona dispune de facilități logistice extinse, stații vamale și depozite concepute pentru a procesa mii de camioane zilnic. Din punct de vedere economic, acest sit reprezintă coloana vertebrală a relațiilor economice Myanmar-China și o componentă centrală a Coridorului Economic China-Myanmar. Totuși, instabilitatea politică și închiderile de frontieră cauzate de conflicte sau pandemii au dus în trecut la pierderi economice semnificative.",
      en: "The 105-Mile Trade Zone in Muse, Shan State, is the largest and most vital gateway for land-based trade between Myanmar and China. Strategically positioned along the main highway to Mandalay and directly opposite the Chinese city of Ruili in Yunnan Province, this special trade zone handles the lion's share of Myanmar's total border trade by value. Exports passing through here primarily include agricultural products, fruits, rice, and seafood, while imports consist of machinery, fuel, and manufactured consumer goods. The zone features extensive logistics facilities, customs checkpoints, and warehouses designed to facilitate the movement of thousands of trucks daily. Economically, this site is the backbone of Myanmar-China commercial relations and a central component of the China-Myanmar Economic Corridor (CMEC). However, trade flows have been periodically disrupted by regional conflict, political instability, and pandemic-related border closures, leading to significant economic impacts.",
      es: "La Zona de Comercio de las 105 Millas en Myanmar es una ubicación comercial fronteriza clave en la frontera con China, en la región de Shan. Se encuentra a unas 105 millas (169 km) de Lashio, de donde proviene su nombre. La zona se estableció en la década de 1990 y gestiona gran parte del comercio legal entre Myanmar y China. Los bienes principales son productos agrícolas, productos mineros y bienes de consumo. Cientos de camiones cruzan la frontera diariamente. El valor de las mercancías asciende anualmente a varios miles de millones de dólares.",
      pt: "A Zona de Comércio de 105 Milhas em Myanmar é um local de comércio fronteiriço significativo na fronteira com a China, na região de Shan. Localiza-se a cerca de 105 milhas (169 km) de Lashio, daí o seu nome. A zona foi estabelecida na década de 1990 e processa grande parte do comércio legal entre Myanmar e a China. Os principais bens são produtos agrícolas, produtos mineiros e bens de consumo. Diariamente, centenas de camiões atravessam a fronteira. O valor das mercadorias ascende anualmente a vários milhares de milhões de dólares.",
      fr: "La zone commerciale des 105 miles au Myanmar est un site de commerce frontalier majeur à la frontière avec la Chine, dans la région Shan. Elle est située à environ 105 miles (169 km) de Lashio, d'où son nom. La zone a été établie dans les années 1990 et traite une grande partie du commerce légal entre le Myanmar et la Chine. Les principaux produits sont les produits agricoles, les produits miniers et les biens de consommation. Chaque jour, des centaines de camions traversent la frontière. La valeur des marchandises s'élève à plusieurs milliards de dollars par an.",
    },
