      ro: ["Punctul de plecare al conductelor de petrol și gaze către China", "Port de adâncime situat pe insula Ramree", "Parte centrală a Inițiativei 'Belt and Road'", "Acces direct la Oceanul Indian pentru sud-vestul Chinei", "Zona industrială acoperă aproximativ 1.000 de hectare", "Cel mai important factor economic din statul Rakhine"],
      en: ["Starting point for the trans-Myanmar oil and gas pipelines", "Deep-sea port located on Ramree Island", "Key project of China's Belt and Road Initiative", "Provides Southwest China with direct Indian Ocean access", "Industrial park covers approximately 1,000 hectares", "Major economic driver in Rakhine State"],
      es: ["Superficie: 1.000 hectáreas", "Longitud del oleoducto: 770 km", "Longitud del gasoducto: 793 km", "Puesta en marcha del oleoducto: 2017", "Profundidad del puerto: 18 m", "Inversión: más de 1.500 millones de USD"],
