      fr: ["Superficie : 1 000 hectares", "Longueur de l'oléoduc : 770 km", "Longueur du gazoduc : 793 km", "Mise en service de l'oléoduc : 2017", "Profondeur du port : 18 m", "Investissement : plus de 1,5 milliard USD"],
